CHECK_EQ(averageOf({INT_MAX, INT_MIN}).value_or(0.0), -0.5);
CHECK_EQ(averageOf({INT_MAX, INT_MAX}).value_or(0.0), INT_MAX * 1.0);
CHECK_EQ(averageOf({-1000000, 1000000}).value_or(0.0), 0.0);
